INSERT INTO surveillance.anomaly (id, disease_code, level, zone_id, state_id, district_id, week_start, hot_units, confidence, title, body, evidence, is_simulated, needs_epidemiologist_review, status, created_at) VALUES
  ('cfd00000-0602-4000-8000-000000000001', 'lepto', 'district', NULL, NULL, util.seed_district('Pathanamthitta'), '2026-10-12', ARRAY['RNI', 'PRN']::text[], 0.78, 'Leptospirosis rising in Ranni and Perunad', '14 cases this week across the district, 2.0x the 5-year baseline of 7 for week 42; 12 of them in Ranni and Perunad. The rise began 6 days after the 8 Oct flooding along the Pamba.', '["14 cases vs baseline 7 (week 42)", "Onset clustered 6-11 days after flooding", "61% of cases are farm or cleanup workers"]'::jsonb, true, true, 'open', '2026-10-17 06:00:00+05:30'),
  ('cfd00000-0602-4000-8000-000000000002', 'dengue', 'state', NULL, 33, NULL, '2026-10-12', ARRAY['TVM', 'KLM']::text[], 0.81, 'Dengue clusters on the southern coast', 'Thiruvananthapuram and Kollam reported 496 cases this week, 2.3x their baseline of 215. 7 clusters sit along the coastal belt, where breeding sites rose after early rain.', '["496 cases vs baseline 215 (TVM + KLM)", "7 clusters within 2 km of the coast", "NS1 positivity up from 9% to 17%"]'::jsonb, true, true, 'open', '2026-10-17 06:00:00+05:30'),
  ('cfd00000-0602-4000-8000-000000000003', 'dengue', 'zonal', 2, NULL, NULL, '2026-10-12', ARRAY['KA', 'KL']::text[], 0.74, 'Dengue up in Karnataka and Kerala', 'Karnataka (mainly Bengaluru Urban) and Kerala together reported 5,940 cases this week, 1.7x baseline. Tamil Nadu and Andhra Pradesh are within the normal range.', '["5,940 cases vs baseline 3,480", "Bengaluru Urban: 41% of Karnataka cases", "Serotype DENV-2 in 68% of typed samples"]'::jsonb, true, true, 'open', '2026-10-17 06:00:00+05:30'),
  ('cfd00000-0602-4000-8000-000000000004', 'fever', 'central', NULL, NULL, NULL, '2026-10-12', ARRAY['BR', 'UP', 'JH']::text[], 0.69, 'Acute fever up in Bihar, eastern UP and Jharkhand', 'Acute febrile illness in these three states is 1.7x the 5-year baseline for week 42. Children under 15 make up 46% of cases; scrub typhus and Japanese encephalitis tests are pending in 3 districts.', '["3.1 lakh cases vs baseline 1.8 lakh", "46% of cases under 15 years", "Rise follows 3 weeks of flooding in north Bihar"]'::jsonb, true, true, 'open', '2026-10-17 06:00:00+05:30')
